CREATE TABLE _meta("key" VARCHAR, "value" VARCHAR);
CREATE TABLE raw_adjust_factor(symbol VARCHAR, date DATE, hfq_factor DOUBLE);
CREATE TABLE raw_basic_daily(date DATE, symbol VARCHAR, "close" DOUBLE, preclose DOUBLE, change_pct DOUBLE, amplitude DOUBLE, turnover DOUBLE, floatmv DOUBLE, totalmv DOUBLE);
CREATE TABLE raw_gbbq(category BIGINT, symbol VARCHAR, date DATE, c1 DOUBLE, c2 DOUBLE, c3 DOUBLE, c4 DOUBLE);
CREATE TABLE raw_holidays(date DATE);
CREATE TABLE raw_kline_1min(symbol VARCHAR, open DOUBLE, high DOUBLE, low DOUBLE, "close" DOUBLE, amount DOUBLE, volume BIGINT, datetime TIMESTAMP WITH TIME ZONE);
CREATE TABLE raw_kline_daily(symbol VARCHAR, open DOUBLE, high DOUBLE, low DOUBLE, "close" DOUBLE, amount DOUBLE, volume BIGINT, up_count BIGINT, down_count BIGINT, date DATE);
CREATE TABLE raw_symbol_class(symbol VARCHAR, "class" VARCHAR);
CREATE TABLE raw_symbol_name(symbol VARCHAR, "name" VARCHAR, "class" VARCHAR);
CREATE TABLE raw_tdx_blocks_info(block_type VARCHAR, block_name VARCHAR, block_symbol VARCHAR, block_code VARCHAR, parent_code VARCHAR, block_level BIGINT);
CREATE TABLE raw_tdx_blocks_member(stock_symbol VARCHAR, block_code VARCHAR);
CREATE VIEW v_etf_bfq AS WITH latest_factors AS (SELECT symbol, argmax(hfq_factor, date) AS latest_hfq FROM raw_adjust_factor GROUP BY symbol)SELECT s.symbol AS symbol, s.date AS date, s.open AS open, s.high AS high, s.low AS low, s."close" AS "close", b.preclose AS preclose, s.volume AS volume, s.amount AS amount, b.turnover AS turnover, b.floatmv AS floatmv, b.totalmv AS totalmv, b.change_pct AS change_pct, b.amplitude AS amplitude, COALESCE(f.hfq_factor, 1) AS hfq_factor, (COALESCE(f.hfq_factor, 1) / COALESCE(lf.latest_hfq, 1)) AS qfq_factor FROM raw_kline_daily AS s INNER JOIN raw_symbol_class AS sc ON (((s.symbol = sc.symbol) AND (sc."class" = 'etf'))) LEFT JOIN raw_adjust_factor AS f ON (((s.symbol = f.symbol) AND (s.date = f.date))) LEFT JOIN latest_factors AS lf ON ((s.symbol = lf.symbol)) LEFT JOIN raw_basic_daily AS b ON (((s.symbol = b.symbol) AND (s.date = b.date)));
CREATE VIEW v_etf_hfq AS SELECT s.symbol AS symbol, s.date AS date, round((s.open * COALESCE(f.hfq_factor, 1)), 3) AS open, round((s.high * COALESCE(f.hfq_factor, 1)), 3) AS high, round((s.low * COALESCE(f.hfq_factor, 1)), 3) AS low, round((s."close" * COALESCE(f.hfq_factor, 1)), 3) AS "close", round((b.preclose * COALESCE(f.hfq_factor, 1)), 3) AS preclose, s.volume AS volume, s.amount AS amount, b.turnover AS turnover, b.floatmv AS floatmv, b.totalmv AS totalmv, b.change_pct AS change_pct, b.amplitude AS amplitude, COALESCE(f.hfq_factor, 1) AS hfq_factor FROM raw_kline_daily AS s INNER JOIN raw_symbol_class AS sc ON (((s.symbol = sc.symbol) AND (sc."class" = 'etf'))) LEFT JOIN raw_adjust_factor AS f ON (((s.symbol = f.symbol) AND (s.date = f.date))) LEFT JOIN raw_basic_daily AS b ON (((s.symbol = b.symbol) AND (s.date = b.date)));
CREATE VIEW v_etf_qfq AS WITH latest_factors AS (SELECT symbol, argmax(hfq_factor, date) AS latest_hfq FROM raw_adjust_factor GROUP BY symbol)SELECT s.symbol AS symbol, s.date AS date, round(((s.open * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 3) AS open, round(((s.high * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 3) AS high, round(((s.low * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 3) AS low, round(((s."close" * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 3) AS "close", round(((b.preclose * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 3) AS preclose, s.volume AS volume, s.amount AS amount, b.turnover AS turnover, b.floatmv AS floatmv, b.totalmv AS totalmv, b.change_pct AS change_pct, b.amplitude AS amplitude, (COALESCE(f.hfq_factor, 1) / COALESCE(lf.latest_hfq, 1)) AS qfq_factor FROM raw_kline_daily AS s INNER JOIN raw_symbol_class AS sc ON (((s.symbol = sc.symbol) AND (sc."class" = 'etf'))) LEFT JOIN raw_adjust_factor AS f ON (((s.symbol = f.symbol) AND (s.date = f.date))) LEFT JOIN latest_factors AS lf ON ((s.symbol = lf.symbol)) LEFT JOIN raw_basic_daily AS b ON (((s.symbol = b.symbol) AND (s.date = b.date)));
CREATE VIEW v_stock_bfq AS WITH latest_factors AS (SELECT symbol, argmax(hfq_factor, date) AS latest_hfq FROM raw_adjust_factor GROUP BY symbol)SELECT s.symbol AS symbol, s.date AS date, s.open AS open, s.high AS high, s.low AS low, s."close" AS "close", b.preclose AS preclose, s.volume AS volume, s.amount AS amount, b.turnover AS turnover, b.floatmv AS floatmv, b.totalmv AS totalmv, b.change_pct AS change_pct, b.amplitude AS amplitude, COALESCE(f.hfq_factor, 1) AS hfq_factor, (COALESCE(f.hfq_factor, 1) / COALESCE(lf.latest_hfq, 1)) AS qfq_factor FROM raw_kline_daily AS s INNER JOIN raw_symbol_class AS sc ON (((s.symbol = sc.symbol) AND (sc."class" = 'stock'))) LEFT JOIN raw_adjust_factor AS f ON (((s.symbol = f.symbol) AND (s.date = f.date))) LEFT JOIN latest_factors AS lf ON ((s.symbol = lf.symbol)) LEFT JOIN raw_basic_daily AS b ON (((s.symbol = b.symbol) AND (s.date = b.date)));
CREATE VIEW v_stock_hfq AS SELECT s.symbol AS symbol, s.date AS date, round((s.open * COALESCE(f.hfq_factor, 1)), 2) AS open, round((s.high * COALESCE(f.hfq_factor, 1)), 2) AS high, round((s.low * COALESCE(f.hfq_factor, 1)), 2) AS low, round((s."close" * COALESCE(f.hfq_factor, 1)), 2) AS "close", round((b.preclose * COALESCE(f.hfq_factor, 1)), 2) AS preclose, s.volume AS volume, s.amount AS amount, b.turnover AS turnover, b.floatmv AS floatmv, b.totalmv AS totalmv, b.change_pct AS change_pct, b.amplitude AS amplitude, COALESCE(f.hfq_factor, 1) AS hfq_factor FROM raw_kline_daily AS s INNER JOIN raw_symbol_class AS sc ON (((s.symbol = sc.symbol) AND (sc."class" = 'stock'))) LEFT JOIN raw_adjust_factor AS f ON (((s.symbol = f.symbol) AND (s.date = f.date))) LEFT JOIN raw_basic_daily AS b ON (((s.symbol = b.symbol) AND (s.date = b.date)));
CREATE VIEW v_stock_qfq AS WITH latest_factors AS (SELECT symbol, argmax(hfq_factor, date) AS latest_hfq FROM raw_adjust_factor GROUP BY symbol)SELECT s.symbol AS symbol, s.date AS date, round(((s.open * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 2) AS open, round(((s.high * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 2) AS high, round(((s.low * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 2) AS low, round(((s."close" * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 2) AS "close", round(((b.preclose * COALESCE(f.hfq_factor, 1)) / COALESCE(lf.latest_hfq, 1)), 2) AS preclose, s.volume AS volume, s.amount AS amount, b.turnover AS turnover, b.floatmv AS floatmv, b.totalmv AS totalmv, b.change_pct AS change_pct, b.amplitude AS amplitude, (COALESCE(f.hfq_factor, 1) / COALESCE(lf.latest_hfq, 1)) AS qfq_factor FROM raw_kline_daily AS s INNER JOIN raw_symbol_class AS sc ON (((s.symbol = sc.symbol) AND (sc."class" = 'stock'))) LEFT JOIN raw_adjust_factor AS f ON (((s.symbol = f.symbol) AND (s.date = f.date))) LEFT JOIN latest_factors AS lf ON ((s.symbol = lf.symbol)) LEFT JOIN raw_basic_daily AS b ON (((s.symbol = b.symbol) AND (s.date = b.date)));